function resolveModelUrl(rel: string): string {
  // BASE_URL is '/' in dev and './' in the build (vite base './'); resolve against the document either way.
  const base = import.meta.env?.BASE_URL ?? './';
  return new URL(base + rel, document.baseURI).href;
}

