// ───────────────────────────────────────────────────────────────── procedural textures
// Pure functions returning RGBA bytes (exported for tests/playerCar.test.ts); textureFrom() wraps them.
// Every map wraps around its edges, so it tiles without seams.

/** Encode a tangent-space normal (x, y, z; need not be unit length) into RGBA bytes at offset o. */
function putNormal(data: Uint8Array, o: number, x: number, y: number, z: number): void {
  const l = Math.hypot(x, y, z) || 1;
  data[o] = Math.round(((x / l) * 0.5 + 0.5) * 255);
  data[o + 1] = Math.round(((y / l) * 0.5 + 0.5) * 255);
  data[o + 2] = Math.round(((z / l) * 0.5 + 0.5) * 255);
  data[o + 3] = 255;
}

/** 32-bit integer hash (deterministic, no state). */
function hash32(x: number, y: number, seed: number): number {
  let h = Math.imul(x, 0x27d4eb2d) ^ Math.imul(y, 0x165667b1) ^ Math.imul(seed, 0x9e3779b1);
  h = Math.imul(h ^ (h >>> 15), 0x85ebca6b);
  h = Math.imul(h ^ (h >>> 13), 0xc2b2ae35);
  return (h ^ (h >>> 16)) >>> 0;
}

/**
 * Small water beads for the clearcoat. Each bead is a spherical cap; beads do not overlap (rejection
 * sampling) so the result reads as droplets, not noise. Beads crossing an edge continue on the opposite
 * edge. `offset` moves every bead by whole pixels (tests use it to prove the tile wraps).
 */
export function makeRainBeadData(size = 512, count = 1400, seed = 1337, offset: [number, number] = [0, 0]): Uint8Array {
  const data = new Uint8Array(size * size * 4);
  for (let i = 0; i < size * size; i++) putNormal(data, i * 4, 0, 0, 1);
  let s = seed >>> 0;
  const rnd = () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
  const wrap = (v: number) => ((v % size) + size) % size;
  const occ = new Uint8Array(size * size);
  for (let n = 0; n < count; n++) {
    // many small beads, few large ones
    const r = 1.6 + Math.pow(rnd(), 3) * 7.5;
    const cx = rnd() * size + offset[0], cy = rnd() * size + offset[1];
    const fx = Math.floor(cx), fy = Math.floor(cy);
    const ri = Math.ceil(r);
    let free = true;
    for (let y = -ri; y <= ri && free; y += 2)
      for (let x = -ri; x <= ri; x += 2) {
        if (x * x + y * y > r * r) continue;
        if (occ[wrap(fy + y) * size + wrap(fx + x)]) { free = false; break; }
      }
    if (!free) continue;
    for (let y = -ri - 1; y <= ri + 1; y++)
      for (let x = -ri - 1; x <= ri + 1; x++) {
        const dx = fx + x + 0.5 - cx, dy = fy + y + 0.5 - cy;
        const q = (dx * dx + dy * dy) / (r * r);
        if (q >= 1) continue;
        const px = wrap(fx + x), py = wrap(fy + y);
        occ[py * size + px] = 1;
        // spherical-cap slope, a bit flattened in the centre like a real sessile drop
        const k = 0.85;
        const nx = (dx / r) * k, ny = (dy / r) * k;
        putNormal(data, (py * size + px) * 4, nx, -ny, Math.sqrt(Math.max(0.05, 1 - nx * nx - ny * ny)));
      }
  }
  return data;
}

/**
 * Metallic flake: square flakes of `flakePx` pixels, each tilted at random (about 60 % of them strongly,
 * the rest nearly flat, so only some catch the light at a time). size must be a multiple of flakePx.
 */
export function makeFlakeNormalData(size = 256, flakePx = 2, seed = 7): Uint8Array {
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const h = hash32(Math.floor(x / flakePx), Math.floor(y / flakePx), seed);
      const strong = (h & 0xff) < 154;
      const r = ((h >>> 8) & 0xff) / 255;
      const tilt = strong ? 0.25 + 0.45 * r : 0.06 * r;
      const az = (((h >>> 16) & 0xffff) / 65536) * Math.PI * 2;
      putNormal(data, (y * size + x) * 4, Math.sin(tilt) * Math.cos(az), Math.sin(tilt) * Math.sin(az), Math.cos(tilt));
    }
  return data;
}

/**
 * 2/2 twill: is the warp tow (running along v, one per column of tow cells) on top in cell (i, j)?
 * Every tow goes over two, under two; the pattern steps one cell per row, so it repeats every 4 cells.
 */
export function twillWarpOver(i: number, j: number): boolean {
  return (((j - i) % 4) + 4) % 4 < 2;
}

/**
 * Carbon-fibre 2/2 twill: albedo (grey multiplier, linear) and normal map of `tows` × `tows` tow cells of
 * `towPx` pixels; tows must be a multiple of 4 (the weave period). Each visible tow is a rounded bundle
 * that dips at both ends where it goes under the crossing tows; warp and weft differ a little in
 * brightness (stands in for the direction-dependent sheen of real carbon).
 */
export function makeCarbonWeaveData(towPx = WEAVE_TOW_PX, tows = WEAVE_TOWS): { size: number; albedo: Uint8Array; normal: Uint8Array } {
  const size = towPx * tows;
  const height = new Float32Array(size * size);
  const shade = new Float32Array(size * size);
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const i = Math.floor(x / towPx), j = Math.floor(y / towPx);
      const s = (x + 0.5) / towPx - i, t = (y + 0.5) / towPx - j;
      const m = (((j - i) % 4) + 4) % 4;
      const warp = twillWarpOver(i, j);
      // across: 0..1 over the tow width; along: 0..1 over the two cells the tow stays on top
      const across = warp ? s : t;
      const along = warp ? (m + t) / 2 : (3 - m + s) / 2;
      const cross = Math.pow(Math.sin(Math.PI * across), 0.6);
      height[y * size + x] = cross * (0.55 + 0.45 * Math.sin(Math.PI * along));
      // fibre striations along the tow, darker gaps between tows
      const fibre = 0.93 + 0.07 * Math.cos(Math.PI * 2 * across * 4);
      shade[y * size + x] = (warp ? 1 : 0.72) * (0.5 + 0.5 * cross) * fibre;
    }
  const albedo = new Uint8Array(size * size * 4);
  const normal = new Uint8Array(size * size * 4);
  const at = (x: number, y: number) => height[(((y % size) + size) % size) * size + (((x % size) + size) % size)];
  const k = towPx * 0.25; // slope scale: about 40° at the tow edges before normalScale
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const o = (y * size + x) * 4;
      const g = Math.round(Math.min(1, shade[y * size + x]) * 255);
      albedo[o] = albedo[o + 1] = albedo[o + 2] = g;
      albedo[o + 3] = 255;
      const dhx = (at(x + 1, y) - at(x - 1, y)) * 0.5, dhy = (at(x, y + 1) - at(x, y - 1)) * 0.5;
      putNormal(normal, o, -dhx * k, -dhy * k, 1);
    }
  return { size, albedo, normal };
}

/** Tile height in pixels of the hexagonal mesh for a cell `cellPx` wide (even, ≈ cellPx·√3). */
export function hexTileHeight(cellPx: number): number {
  return 2 * Math.round((cellPx * Math.sqrt(3)) / 2);
}

/**
 * Hexagonal metal mesh (pointy-top cells, flats left and right). One tile is one cell wide and two rows
 * tall (the hexagonal lattice is rectangular with an aspect of 1 : √3), `repeat` tiles each way (tests).
 * `wire` is the wire width as a fraction of the cell pitch.
 *  - albedo: grey multiplier, bright wire (a little brighter along its crown), near-black holes,
 *  - normal: rounded wires, flat holes,
 *  - orm: R ambient occlusion (holes deep), G roughness, B metalness (the material's roughness and
 *    metalness are 1 and multiply these), so far away the mip average is one even dark satin metal.
 * Everything is supersampled 4 × 4 per pixel, so the wire edges are anti-aliased in every mip level.
 */
export function makeHexMeshData(cellPx = MESH_CELL_PX, wire = MESH_WIRE_M / MESH_CELL_M, repeat = 1): {
  width: number; height: number; albedo: Uint8Array; normal: Uint8Array; orm: Uint8Array;
} {
  const tw = cellPx, th = hexTileHeight(cellPx);
  const width = tw * repeat, height = th * repeat;
  const S3 = Math.sqrt(3);
  const hw = wire / 2;
  // lattice units: cell pitch 1, the tile spans 1 × √3
  const sample = (u: number, v: number): { h: number; w: number } => {
    const x = u, y = v * S3;
    const ax = x - Math.round(x), ay = y - Math.round(y / S3) * S3;
    const bx = x - (Math.floor(x) + 0.5), by = y - (Math.floor(y / S3) + 0.5) * S3;
    const [qx, qy] = ax * ax + ay * ay <= bx * bx + by * by ? [ax, ay] : [bx, by];
    const hex = Math.max(Math.abs(qx), 0.5 * Math.abs(qx) + (S3 / 2) * Math.abs(qy));
    const g = 0.5 - hex; // distance to the cell border
    return g < hw ? { h: Math.cos((Math.PI / 2) * (g / hw)), w: 1 } : { h: 0, w: 0 };
  };
  const SS = 4;
  const hgt = new Float32Array(width * height), cov = new Float32Array(width * height);
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++) {
      let h = 0, w = 0;
      for (let j = 0; j < SS; j++)
        for (let i = 0; i < SS; i++) {
          const s = sample((x + (i + 0.5) / SS) / tw, (y + (j + 0.5) / SS) / th);
          h += s.h;
          w += s.w;
        }
      hgt[y * width + x] = h / (SS * SS);
      cov[y * width + x] = w / (SS * SS);
    }
  const albedo = new Uint8Array(width * height * 4), normal = new Uint8Array(width * height * 4);
  const orm = new Uint8Array(width * height * 4);
  const at = (x: number, y: number) => hgt[(((y % height) + height) % height) * width + (((x % width) + width) % width)];
  const k = 3.2; // slope scale: the wire flanks tilt up to about 45°
  const b = (v: number) => Math.round(Math.min(1, Math.max(0, v)) * 255);
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++) {
      const i = y * width + x, o = i * 4;
      const c = cov[i], h = hgt[i];
      albedo[o] = albedo[o + 1] = albedo[o + 2] = b(c * (0.78 + 0.22 * h) + (1 - c) * 0.1);
      albedo[o + 3] = 255;
      orm[o] = b(c + (1 - c) * 0.3); // occlusion
      orm[o + 1] = b(c * 0.35 + (1 - c) * 0.62); // roughness
      orm[o + 2] = b(c * 0.6 + (1 - c) * 0.2); // metalness
      orm[o + 3] = 255;
      const dhx = (at(x + 1, y) - at(x - 1, y)) * 0.5, dhy = (at(x, y + 1) - at(x, y - 1)) * 0.5;
      putNormal(normal, o, -dhx * k, -dhy * k, 1);
    }
  return { width, height, albedo, normal, orm };
}

/** Repeat-wrapped, mipmapped texture over RGBA bytes (linear data: normals, multipliers). */
function textureFrom(data: Uint8Array, w: number, h: number, tileW: number, tileH = tileW): DataTexture {
  const tex = new DataTexture(data, w, h, RGBAFormat);
  tex.colorSpace = NoColorSpace;
  tex.wrapS = tex.wrapT = RepeatWrapping;
  tex.magFilter = LinearFilter;
  tex.minFilter = LinearMipmapLinearFilter;
  tex.generateMipmaps = true;
  // the model's UVs are in metres
  tex.repeat.set(1 / tileW, 1 / tileH);
  tex.needsUpdate = true;
  return tex;
}

interface CarTextures {
  beads: DataTexture;
  flake: DataTexture;
  weaveAlbedo: DataTexture;
  weaveNormal: DataTexture;
  meshAlbedo: DataTexture;
  meshNormal: DataTexture;
  meshOrm: DataTexture;
  /** Far-away values of the patterns (see patchPatternFade). */
  means: { weaveAlbedo: number; mesh: PatternMeans };
}

function makeCarTextures(): CarTextures {
  const weave = makeCarbonWeaveData();
  const weaveTile = CARBON_TOW_M * WEAVE_TOWS;
  const hex = makeHexMeshData();
  const hexW = MESH_CELL_M, hexH = MESH_CELL_M * Math.sqrt(3);
  return {
    means: {
      weaveAlbedo: channelMean(weave.albedo, 0),
      mesh: { albedo: channelMean(hex.albedo, 0), ao: channelMean(hex.orm, 0), rough: channelMean(hex.orm, 1), metal: channelMean(hex.orm, 2) },
    },
    beads: textureFrom(makeRainBeadData(512), 512, 512, BEAD_TILE_M),
    flake: textureFrom(makeFlakeNormalData(256), 256, 256, FLAKE_TILE_M),
    weaveAlbedo: textureFrom(weave.albedo, weave.size, weave.size, weaveTile),
    weaveNormal: textureFrom(weave.normal, weave.size, weave.size, weaveTile),
    meshAlbedo: textureFrom(hex.albedo, hex.width, hex.height, hexW, hexH),
    meshNormal: textureFrom(hex.normal, hex.width, hex.height, hexW, hexH),
    meshOrm: textureFrom(hex.orm, hex.width, hex.height, hexW, hexH),
  };
}

// ───────────────────────────────────────────────────────────────── shader patches
// Small onBeforeCompile edits of three's physical shader. Each one chains the previous hook (the lighting
// patch is added later and chains these) and extends the program cache key, so patched and unpatched
// materials never share a program.

function addPatch(m: Material, key: string, edit: (shader: { fragmentShader: string; uniforms: Record<string, { value: unknown }> }) => void): void {
  const prev = m.onBeforeCompile;
  m.onBeforeCompile = (shader, renderer) => {
    prev?.call(m, shader, renderer);
    edit(shader);
  };
  const prevKey = m.customProgramCacheKey;
  m.customProgramCacheKey = () => (prevKey ? prevKey.call(m) : '') + '|' + key;
}

const glslF = (v: number) => v.toFixed(4);

/**
 * Rain beads on the clearcoat fade with their screen footprint (texels per pixel along the longer axis of
 * the pixel footprint, so grazing views fade too) and with `gain` (lowered while the camera sits on the
 * car: the bonnet camera); the clearcoat roughens by `sheen` as they fade.
 */
function patchBeadFade(m: MeshPhysicalMaterial, sheen: { value: number }, gain: { value: number }): void {
  addPatch(m, 'nsBeads', (shader) => {
    shader.uniforms.nsBeadSheen = sheen;
    shader.uniforms.nsBeadGain = gain;
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', '#include <common>\nuniform float nsBeadSheen;\nuniform float nsBeadGain;')
      .replace('#include <clearcoat_normal_fragment_begin>', '#include <clearcoat_normal_fragment_begin>\nfloat nsBeadFade = 0.0;')
      .replace(
        '#include <clearcoat_normal_fragment_maps>',
        `#ifdef USE_CLEARCOAT_NORMALMAP
{
  float nsTpx = max(length(dFdx(vClearcoatNormalMapUv)), length(dFdy(vClearcoatNormalMapUv))) * 512.0;
  nsBeadFade = (1.0 - smoothstep(${glslF(BEAD_FULL_TPX)}, ${glslF(BEAD_ZERO_TPX)}, nsTpx)) * nsBeadGain;
  vec3 clearcoatMapN = texture2D(clearcoatNormalMap, vClearcoatNormalMapUv).xyz * 2.0 - 1.0;
  clearcoatMapN.xy *= clearcoatNormalScale * nsBeadFade;
  clearcoatNormal = normalize(tbn2 * clearcoatMapN);
}
#endif`,
      )
      .replace(
        '#include <lights_physical_fragment>',
        `#include <lights_physical_fragment>
#ifdef USE_CLEARCOAT
material.clearcoatRoughness = min(1.0, material.clearcoatRoughness + nsBeadSheen * (1.0 - nsBeadFade));
#endif`,
      );
  });
}

/** Mean values of a pattern's maps (0..1), what it should look like from far away. */
export interface PatternMeans { albedo?: number; ao?: number; rough?: number; metal?: number }

/** Mean of one channel of RGBA bytes, 0..1. */
export function channelMean(data: Uint8Array, c: number): number {
  let s = 0;
  for (let i = c; i < data.length; i += 4) s += data[i];
  return s / (data.length / 4) / 255;
}

/**
 * Fine patterns (carbon weave, metal mesh) fade to their far-away look before the GPU's mip chain starts
 * to alias them (no sparkle, no moiré, no row banding): the screen footprint in texels per pixel is taken
 * along the longer axis of the pixel footprint (`texels` = the maps' size in texels). The normal relief is
 * full up to `normal[0]` texels per pixel and gone at `normal[1]`; the base roughness rises by `rough` as
 * it goes. Colour / occlusion / roughness / metalness maps blend to their `means` between `maps[0]` and
 * `maps[1]` texels per pixel. All the maps share one UV transform.
 */
function patchPatternFade(
  m: MeshStandardMaterial, key: string, texels: [number, number], normal: [number, number], rough: number,
  maps: [number, number], means: PatternMeans,
): void {
  addPatch(m, `nsFade_${key}`, (shader) => {
    let fs = shader.fragmentShader;
    const mix = (mean: number | undefined, expr: string) => (mean === undefined ? expr : `mix(${glslF(mean)}, ${expr}, nsMapFade)`);
    fs = fs.replace(
      '#include <map_fragment>',
      `float nsNFade = 1.0, nsMapFade = 1.0;
#if defined( USE_NORMALMAP_TANGENTSPACE )
{
  vec2 nsT = vec2(${glslF(texels[0])}, ${glslF(texels[1])});
  float nsTpx = max(length(dFdx(vNormalMapUv) * nsT), length(dFdy(vNormalMapUv) * nsT));
  nsNFade = 1.0 - smoothstep(${glslF(normal[0])}, ${glslF(normal[1])}, nsTpx);
  nsMapFade = 1.0 - smoothstep(${glslF(maps[0])}, ${glslF(maps[1])}, nsTpx);
}
#endif
` +
        (means.albedo === undefined
          ? ShaderChunk.map_fragment
          : ShaderChunk.map_fragment.replace(
              'diffuseColor *= sampledDiffuseColor;',
              `sampledDiffuseColor.rgb = mix(vec3(${glslF(means.albedo)}), sampledDiffuseColor.rgb, nsMapFade);
	diffuseColor *= sampledDiffuseColor;`,
            )),
    );
    fs = fs
      .replace('#include <roughnessmap_fragment>', ShaderChunk.roughnessmap_fragment.replace('texelRoughness.g;', mix(means.rough, 'texelRoughness.g') + ';'))
      .replace('#include <metalnessmap_fragment>', ShaderChunk.metalnessmap_fragment.replace('texelMetalness.b;', mix(means.metal, 'texelMetalness.b') + ';'))
      .replace('#include <aomap_fragment>', ShaderChunk.aomap_fragment.replace('texture2D( aoMap, vAoMapUv ).r', mix(means.ao, 'texture2D( aoMap, vAoMapUv ).r')))
      .replace('#include <normal_fragment_maps>', ShaderChunk.normal_fragment_maps.replace('mapN.xy *= normalScale;', 'mapN.xy *= normalScale * nsNFade;'))
      .replace(
        '#include <lights_physical_fragment>',
        `#include <lights_physical_fragment>
material.roughness = min(1.0, material.roughness + ${glslF(rough)} * (1.0 - nsNFade));`,
      );
    shader.fragmentShader = fs;
  });
}

/**
 * Glass: 'reflection over tint'. The colour is nearly black, so the shaded colour is almost only the
 * specular / environment reflection; it is added at full strength (blend source factor ONE) while alpha
 * only darkens what lies behind (destination × (1 − alpha)). Alpha rises towards `edge` at grazing
 * angles (Schlick), so side windows seen along the car turn into dark mirrors.
 */
function patchGlass(m: MeshPhysicalMaterial, edge: number): void {
  m.blending = CustomBlending;
  m.blendEquation = AddEquation;
  m.blendSrc = OneFactor;
  m.blendDst = OneMinusSrcAlphaFactor;
  m.premultipliedAlpha = false;
  if (edge <= m.opacity) return;
  addPatch(m, 'nsGlass', (shader) => {
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <opaque_fragment>',
      `diffuseColor.a = mix(diffuseColor.a, max(diffuseColor.a, ${glslF(edge)}), pow(1.0 - saturate(dot(normal, normalize(vViewPosition))), 5.0));
#include <opaque_fragment>`,
    );
  });
}

// ───────────────────────────────────────────────────────────────── geometry merge helpers

interface Piece {
  geometry: BufferGeometry;
  matrix: Matrix4;
  bone: number;
}

/**
 * Merge rigid pieces (each bound to one bone) into one skinned geometry in car space.
 * UVs: the model's TEXCOORD_0 (metres); a piece without one gets a box projection in car space, also in
 * metres, so the procedural maps still tile at the right scale. COLOR_0 (baked occlusion) is carried only
 * if every piece has it.
 */
function mergeSkinned(pieces: Piece[]): BufferGeometry {
  const hasColor = pieces.every((p) => p.geometry.getAttribute('color'));
  let vCount = 0, iCount = 0;
  for (const p of pieces) {
    const n = p.geometry.getAttribute('position').count;
    vCount += n;
    iCount += p.geometry.index ? p.geometry.index.count : n;
  }
  const pos = new Float32Array(vCount * 3), nrm = new Float32Array(vCount * 3);
  const uv = new Float32Array(vCount * 2);
  const col = hasColor ? new Float32Array(vCount * 3) : null;
  const skinIndex = new Uint16Array(vCount * 4), skinWeight = new Float32Array(vCount * 4);
  const index = vCount > 65535 ? new Uint32Array(iCount) : new Uint16Array(iCount);
  const v = new Vector3(), n3 = new Vector3(), nm = new Matrix3();
  let vo = 0, io = 0;
  for (const p of pieces) {
    const g = p.geometry;
    const P = g.getAttribute('position'), N = g.getAttribute('normal');
    const U = g.getAttribute('uv'), C = g.getAttribute('color');
    nm.getNormalMatrix(p.matrix);
    const flip = p.matrix.determinant() < 0;
    for (let i = 0; i < P.count; i++) {
      v.fromBufferAttribute(P, i).applyMatrix4(p.matrix);
      pos.set([v.x, v.y, v.z], (vo + i) * 3);
      if (N) n3.fromBufferAttribute(N, i).applyNormalMatrix(nm);
      else n3.set(0, 1, 0);
      nrm.set([n3.x, n3.y, n3.z], (vo + i) * 3);
      if (U) uv.set([U.getX(i), U.getY(i)], (vo + i) * 2);
      else {
        // box projection: drop the axis the normal points along most
        const ax = Math.abs(n3.x), ay = Math.abs(n3.y), az = Math.abs(n3.z);
        if (ax >= ay && ax >= az) uv.set([v.z, v.y], (vo + i) * 2);
        else if (ay >= az) uv.set([v.x, v.z], (vo + i) * 2);
        else uv.set([v.x, v.y], (vo + i) * 2);
      }
      if (col && C) col.set([C.getX(i), C.getY(i), C.getZ(i)], (vo + i) * 3);
      skinIndex[(vo + i) * 4] = p.bone;
      skinWeight[(vo + i) * 4] = 1;
    }
    const idx = g.index;
    const n = idx ? idx.count : P.count;
    for (let t = 0; t < n; t += 3) {
      const a = idx ? idx.getX(t) : t, b = idx ? idx.getX(t + 1) : t + 1, c = idx ? idx.getX(t + 2) : t + 2;
      index[io + t] = vo + a;
      index[io + t + 1] = vo + (flip ? c : b);
      index[io + t + 2] = vo + (flip ? b : c);
    }
    vo += P.count;
    io += n;
  }
  const out = new BufferGeometry();
  out.setAttribute('position', new BufferAttribute(pos, 3));
  out.setAttribute('normal', new BufferAttribute(nrm, 3));
  out.setAttribute('uv', new BufferAttribute(uv, 2));
  if (col) out.setAttribute('color', new BufferAttribute(col, 3));
  out.setAttribute('skinIndex', new Uint16BufferAttribute(skinIndex, 4));
  out.setAttribute('skinWeight', new BufferAttribute(skinWeight, 4));
  out.setIndex(new BufferAttribute(index, 1));
  out.computeBoundingBox();
  out.computeBoundingSphere();
  return out;
}

// ───────────────────────────────────────────────────────────────── materials

type AnyLit = MeshStandardMaterial | MeshPhysicalMaterial;

/** Base env-map multipliers per material (setEnvMap's intensity is multiplied by these). */
const ENV_GAIN: Record<string, number> = {
  paint_main: 1, paint_accent: 1, carbon: 1, glass: 2, lens: 1.8, mirror: 1.2, reflector: 1.2, rim_chrome: 1.1,
  hardware: 1, disc: 0.9, reverse: 0.6,
};

/**
 * One material per name in tools/car/lib/materials.py DEFS. Scalar factors come from the file where it has
 * them; textures never do (the file has none): paint flake, carbon weave and rain beads are made in code.
 */
function buildMaterials(src: Map<string, Material>, tex: CarTextures): Map<string, AnyLit> {
  const get = (name: string) => src.get(name) as AnyLit | undefined;
  const out = new Map<string, AnyLit>();
  const std = (name: string): MeshStandardMaterial => {
    const s = get(name);
    const m = new MeshStandardMaterial();
    if (s) {
      m.color.copy(s.color);
      m.metalness = s.metalness;
      m.roughness = s.roughness;
      m.emissive.copy(s.emissive);
      m.emissiveIntensity = s.emissiveIntensity;
      m.side = s.side;
    }
    m.name = name;
    return m;
  };

  // ── car paint: metallic base + flake normal, mirror-like clearcoat with very subtle rain beads
  for (const name of ['paint_main', 'paint_accent']) {
    const s = get(name);
    const m = new MeshPhysicalMaterial({ name });
    if (s) m.side = s.side;
    m.normalMap = tex.flake;
    m.clearcoat = 1;
    m.clearcoatRoughness = 0.04;
    m.clearcoatNormalMap = tex.beads;
    m.clearcoatNormalScale = new Vector2(0.18, 0.18);
    m.iridescenceIOR = 1.45;
    m.iridescenceThicknessMinimum = 180;
    m.iridescenceThicknessMaximum = 520;
    out.set(name, m);
  }

  // ── bare carbon fibre: twill weave (albedo multiplier + normal) under a clearcoat that also gets the beads
  {
    const s = get('carbon');
    const m = new MeshPhysicalMaterial({ name: 'carbon', color: new Color(0.034, 0.035, 0.038), metalness: 0.3, roughness: 0.38 });
    if (s) m.side = s.side;
    m.map = tex.weaveAlbedo;
    m.normalMap = tex.weaveNormal;
    m.normalScale.set(CARBON_NORMAL, CARBON_NORMAL);
    m.clearcoat = 1;
    m.clearcoatRoughness = 0.06;
    m.clearcoatNormalMap = tex.beads;
    m.clearcoatNormalScale = new Vector2(0.18, 0.18);
    out.set('carbon', m);
  }

  // ── glass: dark tint with the reflection on top (patchGlass); no transmission → no extra scene pass
  {
    const m = new MeshPhysicalMaterial({
      name: 'glass',
      color: new Color(0.008, 0.009, 0.011),
      metalness: 0,
      roughness: 0.02,
      transparent: true,
      opacity: GLASS_OPACITY,
      depthWrite: false,
      side: DoubleSide,
      specularIntensity: 1,
      ior: 1.52,
    });
    out.set('glass', m);
  }
  // ── lamp covers: clear, glossy, drawn after the opaque lamps behind them. Nearly black colour and a low
  //    alpha: the reflection lies on top, the lamps behind lose only LENS_OPACITY of their light.
  {
    const m = new MeshPhysicalMaterial({
      name: 'lens',
      color: new Color(0.006, 0.006, 0.007),
      metalness: 0,
      roughness: 0.03,
      transparent: true,
      opacity: LENS_OPACITY,
      depthWrite: false,
      side: DoubleSide,
      specularIntensity: 1,
      ior: 1.49,
    });
    out.set('lens', m);
  }

  // ── trims / interior
  const trim = std('trim');
  trim.roughness = 0.65;
  out.set('trim', trim);
  const grille = std('grille');
  grille.color.setRGB(0.003, 0.003, 0.003);
  grille.metalness = 0.1;
  grille.roughness = 0.8;
  out.set('grille', grille);
  // hexagonal metal mesh: dark satin wire over deep holes (albedo / normal / occlusion-roughness-metalness
  // maps made in code; roughness and metalness 1 so the map carries both)
  {
    const m = std('grille_mesh');
    m.color.setRGB(0.035, 0.035, 0.037);
    m.metalness = 1;
    m.roughness = 1;
    m.map = tex.meshAlbedo;
    m.normalMap = tex.meshNormal;
    m.normalScale.set(1, 1);
    m.aoMap = tex.meshOrm;
    m.aoMapIntensity = 1;
    m.roughnessMap = tex.meshOrm;
    m.metalnessMap = tex.meshOrm;
    m.emissive.setRGB(0, 0, 0);
    out.set('grille_mesh', m);
  }
  out.set('mechanical', std('mechanical'));
  const interior = std('interior');
  interior.color.setRGB(0.012, 0.012, 0.013);
  interior.roughness = 0.75;
  out.set('interior', interior);
  // seat accents: dark oxblood leather, low sheen (does not read as a lit shape through the glass)
  const intAcc = std('interior_accent');
  intAcc.color.setRGB(0.03, 0.0055, 0.006);
  intAcc.metalness = 0;
  intAcc.roughness = 0.78;
  out.set('interior_accent', intAcc);
  // screens: dim, desaturated navy
  const dash = std('dashboard');
  dash.emissive.setRGB(0.3, 0.42, 0.62);
  dash.emissiveIntensity = DASH_GLOW;
  out.set('dashboard', dash);
  const hw = std('hardware');
  hw.roughness = 0.32;
  out.set('hardware', hw);
  const mirror = std('mirror');
  mirror.color.setRGB(0.9, 0.9, 0.9);
  mirror.roughness = 0.02;
  out.set('mirror', mirror);
  const plate = std('plate');
  plate.color.setRGB(0.015, 0.016, 0.018);
  plate.metalness = 0.3;
  plate.roughness = 0.45;
  out.set('plate', plate);

  // ── lights: lamps are near-black, all the look comes from HDR emissive
  for (const name of ['headlight_L', 'headlight_R']) {
    const m = std(name);
    m.color.setRGB(0.02, 0.02, 0.022);
    m.metalness = 0.6;
    m.roughness = 0.15;
    m.emissive.setRGB(0.86, 0.93, 1.0);
    m.emissiveIntensity = HEADLIGHT_ON;
    m.toneMapped = true;
    out.set(name, m);
  }
  {
    const m = std('taillight');
    m.color.setRGB(0.03, 0.002, 0.002);
    m.roughness = 0.2;
    m.emissive.setRGB(1, 0.018, 0.01);
    m.emissiveIntensity = TAIL_RUNNING;
    out.set('taillight', m);
  }
  // reverse lenses: a dark clear lens over a reflector, white only in reverse gear
  {
    const m = std('reverse');
    // satin, not glossy: a sharp street-lamp glint on it would read as a lit white lamp
    m.color.setRGB(0.025, 0.025, 0.027);
    m.metalness = 0;
    m.roughness = 0.35;
    m.emissive.setRGB(1, 0.96, 0.9);
    m.emissiveIntensity = 0;
    out.set('reverse', m);
  }
  {
    const m = std('signal');
    m.color.setRGB(0.03, 0.012, 0.002);
    m.roughness = 0.2;
    m.emissive.setRGB(1, 0.35, 0.02);
    m.emissiveIntensity = 0;
    out.set('signal', m);
  }
  // bright metal buckets inside the lamps
  const refl = std('reflector');
  refl.color.setRGB(0.8, 0.8, 0.82);
  refl.metalness = 1;
  refl.roughness = 0.1;
  refl.emissive.setRGB(0, 0, 0);
  out.set('reflector', refl);

  // ── wheels
  const chrome = std('rim_chrome');
  chrome.color.setRGB(0.62, 0.63, 0.65);
  chrome.metalness = 1;
  chrome.roughness = 0.16;
  out.set('rim_chrome', chrome);
  const rimDark = std('rim_dark');
  rimDark.color.setRGB(0.02, 0.02, 0.022);
  rimDark.metalness = 0.7;
  rimDark.roughness = 0.38;
  out.set('rim_dark', rimDark);
  const cal = std('caliper');
  cal.metalness = 0.2;
  cal.roughness = 0.35;
  out.set('caliper', cal);
  const disc = std('disc');
  disc.roughness = 0.42;
  out.set('disc', disc);
  const side = std('tyre_side');
  side.color.setRGB(0.018, 0.018, 0.019);
  side.roughness = 0.72;
  side.metalness = 0;
  out.set('tyre_side', side);
  const tread = std('tyre_tread');
  tread.color.setRGB(0.014, 0.014, 0.015);
  tread.roughness = 0.85;
  tread.metalness = 0;
  out.set('tyre_tread', tread);

  // anything unexpected (tools/car/pack.mjs refuses unknown names): keep the loaded material
  for (const [name, m] of src) if (!out.has(name)) out.set(name, m as AnyLit);
  return out;
}

// ───────────────────────────────────────────────────────────────── body attitude

/**
 * Drawn body attitude: heave (m, + = down), pitch and roll (rad) as the attitude group applies them
 * (rotation (pitch, 0, −roll) about the pivot). For small angles a body point over the wheel at (x, z)
 * moves down by heave + pitch·z + roll·x. If any wheel's corner would drop more than `maxDrop` (its arch
 * would touch the tyre), all three are scaled down together so the worst corner drops exactly `maxDrop`;
 * the direction of the motion is kept. Mutates `a` (no allocation, called every frame).
 */
export function limitAttitude(a: { heave: number; pitch: number; roll: number }, wheels: readonly { x: number; z: number }[], maxDrop: number): void {
  let worst = 0;
  for (const w of wheels) worst = Math.max(worst, a.heave + a.pitch * w.z + a.roll * w.x);
  if (worst <= maxDrop) return;
  const k = maxDrop / worst;
  a.heave *= k;
  a.pitch *= k;
  a.roll *= k;
}

// ───────────────────────────────────────────────────────────────── factory

export async function createPlayerCarVisual(deps: PlayerCarDeps = {}): Promise<PlayerCarVisual> {
  const loader = new GLTFLoader();
  loader.setMeshoptDecoder(MeshoptDecoder);
  const gltf = await loader.loadAsync(deps.url ?? resolveModelUrl(MODEL_URL));
  const src = gltf.scene;
  src.updateMatrixWorld(true);
  let extras = src.userData.nightshift as CarExtras | undefined;
  if (!extras) src.traverse((o) => { if (!extras && o.userData?.nightshift) extras = o.userData.nightshift as CarExtras; });
  if (!extras) throw new Error('player_car.glb: missing nightshift extras (rebuild: tools/car/build_car.py in Blender, then node tools/car/pack.mjs)');
  const X = extras;

  const v3 = (a: readonly number[]) => new Vector3(a[0], a[1], a[2]);

  // ── hierarchy
  const root = new Group();
  root.name = 'PlayerCar';
  const attitude = new Group();
  attitude.name = 'BodyAttitude';
  attitude.position.set(0, ATTITUDE_PIVOT_Y, 0);
  const body = new Group();
  body.name = 'Body';
  body.position.set(0, -ATTITUDE_PIVOT_Y, 0);
  root.add(attitude);
  attitude.add(body);

  const bones: Bone[] = [];
  const boneIndex = new Map<string, number>();
  const addBone = (name: string, parent: Object3D, at?: Vector3): Bone => {
    const b = new Bone();
    b.name = name;
    if (at) b.position.copy(at);
    parent.add(b);
    boneIndex.set(name, bones.length);
    bones.push(b);
    return b;
  };
  addBone('Body', body);
  const mirrorL = addBone('MirrorL', body, v3(X.parts.MirrorL?.pivot ?? [-1, 0.9, -0.3]));
  const mirrorR = addBone('MirrorR', body, v3(X.parts.MirrorR?.pivot ?? [1, 0.9, -0.3]));
  const steering = addBone('Steering', body, v3(X.steering.pivot));
  const steerAxis = v3(X.steering.axis).normalize();

  const order = ['FL', 'FR', 'RL', 'RR'] as const;
  const hubs: Group[] = [];
  const spins: Bone[] = [];
  const wheelLocal: Vector3[] = [];
  for (const key of order) {
    const w = X.wheels.find((q) => q.key === key);
    if (!w) throw new Error(`player_car.glb: wheel ${key} missing from the extras (tools/car/pack.mjs should have refused this file)`);
    const hub = new Group();
    hub.name = `Hub_${key}`;
    hub.position.copy(v3(w.hub));
    root.add(hub);
    hubs.push(hub);
    wheelLocal.push(hub.position.clone());
    spins.push(addBone(`Wheel_${key}_Spin`, hub));
    addBone(`Wheel_${key}_Caliper`, hub);
  }

  // ── anchors (on the body so they follow pitch / roll)
  const mkAnchor = (name: keyof CarExtras['anchors']): Object3D => {
    const o = new Object3D();
    o.name = `Anchor_${name}`;
    o.position.copy(v3(X.anchors[name]));
    body.add(o);
    return o;
  };
  const anchors = {
    headlightL: mkAnchor('headlightL'),
    headlightR: mkAnchor('headlightR'),
    taillightL: mkAnchor('taillightL'),
    taillightR: mkAnchor('taillightR'),
    exhaustL: mkAnchor('exhaustL'),
    exhaustR: mkAnchor('exhaustR'),
    hoodCam: mkAnchor('hoodCam'),
  };

  // ── collect source primitives → (material, bone) pieces
  const partRe = /^(Body|MirrorL|MirrorR|Steering|Wheel_(?:FL|FR|RL|RR)_(?:Spin|Caliper))$/;
  const srcMats = new Map<string, Material>();
  const byMat = new Map<string, Piece[]>();
  src.traverse((o) => {
    const mesh = o as Mesh;
    if (!mesh.isMesh) return;
    let part = '';
    for (let p: Object3D | null = mesh; p; p = p.parent) {
      if (partRe.test(p.name)) { part = p.name; break; }
    }
    if (!part) part = 'Body';
    const mat = mesh.material as Material;
    srcMats.set(mat.name, mat);
    if (!byMat.has(mat.name)) byMat.set(mat.name, []);
    byMat.get(mat.name)!.push({ geometry: mesh.geometry, matrix: mesh.matrixWorld.clone(), bone: boneIndex.get(part)! });
  });

  // bind pose = rest pose with root at identity
  root.updateMatrixWorld(true);
  const skeleton = new Skeleton(bones);
  const tex = makeCarTextures();
  const materials = buildMaterials(srcMats, tex);
  // shader patches (before the lighting patch, which chains them)
  const beadSheen = { value: BEAD_SHEEN }, beadGain = { value: 1 };
  for (const n of ['paint_main', 'paint_accent', 'carbon']) patchBeadFade(materials.get(n) as MeshPhysicalMaterial, beadSheen, beadGain);
  {
    // carbon: relief while a tow (16 texels) spans 4+ px, gone at about 1.3 px; weave colour evens out
    // once a weave period (64 texels) is under 4 px
    const weaveTexels = WEAVE_TOW_PX * WEAVE_TOWS;
    patchPatternFade(materials.get('carbon')!, 'carbon', [weaveTexels, weaveTexels], [4, 12], 0.06, [10, 20], { albedo: tex.means.weaveAlbedo });
    // mesh: full relief while a wire is about 2 px wide, flat once a cell is about 3 px; colour,
    // occlusion, roughness and metalness even out while a cell row (55 texels) goes from 4 to 2 px
    patchPatternFade(materials.get('grille_mesh')!, 'mesh', [MESH_CELL_PX, hexTileHeight(MESH_CELL_PX)], [5, 20], 0.12, [14, 28], tex.means.mesh);
  }
  patchGlass(materials.get('glass') as MeshPhysicalMaterial, GLASS_EDGE);
  patchGlass(materials.get('lens') as MeshPhysicalMaterial, 0);
  const anis = deps.anisotropy ?? 8;
  const meshes: SkinnedMesh[] = [];
  let triangles = 0;
  const camLocal = new Vector3();
  const halfW = X.dims.width / 2, halfL = X.dims.length / 2, topY = X.dims.height + 0.5;
  for (const [name, pieces] of byMat) {
    const geo = mergeSkinned(pieces);
    const m = materials.get(name)!;
    // baked occlusion (COLOR_0 on every piece of this material) darkens the base colour
    if (geo.getAttribute('color')) m.vertexColors = true;
    const sm = new SkinnedMesh(geo, m);
    sm.name = `car_${name}`;
    sm.bind(skeleton);
    // Parts move a few cm at most (wheels yaw, body pitches) → rest bounds + margin are safe.
    const bs = geo.boundingSphere!.clone();
    sm.boundingSphere = new Sphere(bs.center, bs.radius + 0.5);
    // transparent layers after the opaque car: lamp covers, then the windows
    if (name === 'lens') sm.renderOrder = 1;
    if (name === 'glass') sm.renderOrder = 2;
    // The bonnet camera looks at the paint from 10–60 cm: full-size beads there read as glitter. While the
    // camera is over the car's footprint the beads drop to BEAD_ON_CAR (a wet sheen). The gain is a shared
    // uniform of paint and carbon, set just before each of their draws (every pass has its own camera).
    if (name === 'paint_main' || name === 'paint_accent' || name === 'carbon') sm.onBeforeRender = (_r, _s, camera) => {
      camLocal.setFromMatrixPosition(camera.matrixWorld);
      root.worldToLocal(camLocal);
      const on = Math.abs(camLocal.x) < halfW && Math.abs(camLocal.z) < halfL && camLocal.y > 0 && camLocal.y < topY;
      beadGain.value = on ? BEAD_ON_CAR : 1;
    };
    root.add(sm);
    meshes.push(sm);
    triangles += (geo.index?.count ?? 0) / 3;
    for (const p of pieces) p.geometry.dispose();
  }

  // textures (all procedural): anisotropy
  for (const t of Object.values(tex)) if (t instanceof DataTexture) t.anisotropy = anis;

  // lighting hook + env-reflective list
  const allMats = [...new Set(materials.values())];
  if (deps.lighting) for (const m of allMats) deps.lighting.patchDynamic(m);
  const reflective = allMats;

  // layers
  root.traverse((o) => o.layers.set(LAYERS.PLAYER));

  // ── dims (measured by tools/car/build_car.py)
  const D = X.dims;
  const dims: VehicleDims = {
    length: D.length,
    width: D.width,
    height: D.height,
    wheelBase: D.wheelBase,
    trackFront: D.trackFront,
    trackRear: D.trackRear,
    wheelRadius: D.wheelRadius ?? X.wheelRadius,
    frontAxle: D.frontAxle,
    rearAxle: D.rearAxle,
    frontOverhang: D.frontOverhang,
    rearOverhang: D.rearOverhang,
    cgHeight: 0.45,
    mass: 1500,
  };

  // ── state
  const M = (n: string) => materials.get(n);
  const paintMain = M('paint_main') as MeshPhysicalMaterial;
  const paintAcc = M('paint_accent') as MeshPhysicalMaterial;
  const carbon = M('carbon') as MeshPhysicalMaterial;
  const glass = M('glass') as MeshPhysicalMaterial;
  const lens = M('lens') as MeshPhysicalMaterial;
  const headL = M('headlight_L')!, headR = M('headlight_R')!, tail = M('taillight')!, rev = M('reverse')!;
  const caliper = M('caliper')!, caliperRough = caliper.roughness, rimChrome = M('rim_chrome')!, rimDark = M('rim_dark')!, hardware = M('hardware')!;
  let paintName: PaintName = 'graphite';
  let headlightsOn = true, brake = 0, reverse = false, damage = 0, wetness = 1, lowQuality = false;
  let flickerT = 0, flickerOn = true;
  const baseGlassOpacity = glass.opacity, baseLensOpacity = lens.opacity;
  const carbonBase = carbon.color.clone();
  const glassBase = glass.color.clone(), lensBase = lens.color.clone();
  const chromeBase = rimChrome.color.clone(), chromeRough = rimChrome.roughness;
  const rimDarkBase = rimDark.color.clone(), rimDarkRough = rimDark.roughness;
  const hardwareBase = hardware.color.clone();
  // the cabin burns too: seats, trim and screens go dark
  const cabin = ['interior', 'interior_accent', 'dashboard', 'trim'].map((n) => M(n)!).map((m) => ({ m, base: m.color.clone(), glow: m.emissiveIntensity }));
  /** Charred colour of burnt paint and carbon (linear). */
  const CHAR = 0.006;
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  let envIntensity = 1;
  /** Extra env-map factor per material (the burnt wreck loses its gloss). */
  const envDamp = new Map<Material, number>();

  function applyEnv(): void {
    for (const m of reflective) m.envMapIntensity = envIntensity * (ENV_GAIN[m.name] ?? 1) * (envDamp.get(m) ?? 1);
  }

  function applyPaint(): void {
    const p = PAINTS[paintName];
    const d = damage;
    // 0 → 0.8: soot darkening, duller clearcoat, rougher base; 0.8 → 1: burnt to char
    const dark = 1 - 0.55 * d;
    const ch = Math.min(1, Math.max(0, (d - CHAR_FROM) / (1 - CHAR_FROM)));
    const charCol = (c: Color, base: readonly number[], k: number) =>
      c.setRGB(lerp(base[0] * k, CHAR, ch), lerp(base[1] * k, CHAR, ch), lerp(base[2] * k, CHAR, ch));
    charCol(paintMain.color, p.base, dark);
    paintMain.metalness = lerp(p.metalness, 0.15, ch);
    paintMain.roughness = lerp(Math.min(1, p.roughness + 0.35 * d), 0.85, ch);
    paintMain.normalScale.set(p.flake * (1 - ch), p.flake * (1 - ch));
    paintMain.clearcoat = lerp(1 - 0.6 * d, 0.05, ch);
    paintMain.clearcoatRoughness = 0.04 + 0.4 * d;
    paintMain.iridescence = p.iridescence * (1 - ch);
    charCol(paintAcc.color, p.accent, dark);
    paintAcc.metalness = lerp(p.accentMetal, 0.15, ch);
    paintAcc.roughness = lerp(Math.min(1, p.accentRough + 0.35 * d), 0.85, ch);
    paintAcc.normalScale.set(p.flake * 0.8 * (1 - ch), p.flake * 0.8 * (1 - ch));
    paintAcc.clearcoat = lerp(1 - 0.6 * d, 0.05, ch);
    paintAcc.clearcoatRoughness = 0.04 + 0.4 * d;
    charCol(carbon.color, carbonBase.toArray(), dark);
    carbon.roughness = lerp(Math.min(1, 0.38 + 0.35 * d), 0.85, ch);
    carbon.clearcoat = lerp(1 - 0.6 * d, 0.05, ch);
    carbon.clearcoatRoughness = 0.06 + 0.4 * d;
    const calK = lerp(1, 0.12, ch);
    caliper.color.setRGB(p.caliper[0] * calK, p.caliper[1] * calK, p.caliper[2] * calK);
    caliper.roughness = lerp(caliperRough, 0.75, ch);
    rimChrome.color.copy(chromeBase).multiplyScalar(lerp(1, 0.3, ch));
    rimChrome.roughness = lerp(chromeRough, 0.55, ch);
    rimDark.color.copy(rimDarkBase).multiplyScalar(lerp(1, 0.4, ch));
    rimDark.roughness = lerp(rimDarkRough, 0.75, ch);
    hardware.color.copy(hardwareBase).multiplyScalar(lerp(1, 0.3, ch));
    for (const c of cabin) {
      c.m.color.copy(c.base).multiplyScalar(lerp(1, 0.35, ch));
      c.m.emissiveIntensity = c.glow * (1 - ch);
    }
    // rain beads (faded with distance in the shader), off at the low quality preset
    const b = lowQuality ? 0 : BEAD_STRENGTH * wetness;
    paintMain.clearcoatNormalScale.set(b, b);
    paintAcc.clearcoatNormalScale.set(b, b);
    carbon.clearcoatNormalScale.set(b, b);
    beadSheen.value = BEAD_SHEEN * wetness;
    // cracked glass and lamp covers, then dark smoked glass on the burnt wreck (never milky)
    const crack = Math.min(0.4, Math.max(0, d - 0.4));
    glass.opacity = lerp(baseGlassOpacity + 0.2 * crack, 0.75, ch);
    glass.roughness = lerp(0.02 + 0.25 * crack, 0.35, ch);
    glass.color.copy(glassBase).lerp(new Color(CHAR, CHAR, CHAR), ch);
    lens.opacity = lerp(baseLensOpacity + 0.3 * crack, 0.6, ch);
    lens.roughness = lerp(0.03 + 0.3 * crack, 0.35, ch);
    lens.color.copy(lensBase).lerp(new Color(CHAR, CHAR, CHAR), ch);
    for (const m of [paintMain, paintAcc, carbon]) envDamp.set(m, 1 - 0.7 * ch);
    for (const m of [rimChrome, rimDark, hardware]) envDamp.set(m, 1 - 0.6 * ch);
    // sooty glass: a blurred reflection of a bright sky would turn it milky, so it loses most of it
    for (const m of [glass, lens]) envDamp.set(m, 1 - 0.8 * ch);
    applyEnv();
  }

  // Reverse gear: two small white lenses (material 'reverse', optional in the file); the full-width bar
  // stays red at running / brake intensity in every gear.
  const tailRed = new Color(1, 0.018, 0.01);
  tail.emissive.copy(tailRed);

  function applyLights(): void {
    const d = damage;
    const on = headlightsOn ? HEADLIGHT_ON : HEADLIGHT_OFF;
    // left headlight dies at very high damage, right one flickers once damaged
    headL.emissiveIntensity = d > 0.9 ? 0 : on;
    headR.emissiveIntensity = d > 0.5 && !flickerOn ? on * 0.04 : on;
    tail.emissiveIntensity = TAIL_RUNNING + (TAIL_BRAKE - TAIL_RUNNING) * Math.min(1, Math.max(0, brake));
    rev.emissiveIntensity = reverse ? REVERSE_ON : 0;
  }

  function applyDamageParts(): void {
    // mirrors get knocked off (bone collapsed → zero-area triangles, no draw-call change)
    mirrorL.scale.setScalar(damage > 0.6 ? 1e-4 : 1);
    mirrorR.scale.setScalar(damage > 0.85 ? 1e-4 : 1);
  }

  const q = new Quaternion();
  const att = { heave: 0, pitch: 0, roll: 0 };
  let envTex: Texture | null = null;

  const visual: PlayerCarVisual = {
    root,
    dims,
    wheelLocal,
    anchors,
    get paint() { return paintName; },
    drawCalls: meshes.length,
    triangles,

    update(dt: number, state: PlayerState): void {
      root.position.copy(state.position);
      root.quaternion.copy(state.quaternion);

      // body attitude: heave from the mean compression (pitch / roll terms cancel), sign conventions per types.ts
      const s = state.suspension;
      att.heave = Math.max(-MAX_HEAVE, Math.min(MAX_HEAVE, (s[0] + s[1] + s[2] + s[3]) * 0.25));
      att.pitch = state.bodyPitch;
      att.roll = state.bodyRoll;
      limitAttitude(att, wheelLocal, MAX_CORNER_DROP);
      attitude.position.y = ATTITUDE_PIVOT_Y - att.heave;
      attitude.rotation.set(att.pitch, 0, -att.roll, 'XYZ');

      // rain beads are off at the low quality preset (read every frame: the preset can change in play)
      const lowQ = deps.quality?.level === 'low';
      if (lowQ !== lowQuality) {
        lowQuality = lowQ;
        applyPaint();
      }

      // wheels: hubs stay on the ground (the body moves over them), fronts yaw, spin about the axle (X)
      const steer = state.steerAngle;
      hubs[0].rotation.y = -steer;
      hubs[1].rotation.y = -steer;
      for (let i = 0; i < 4; i++) spins[i].rotation.x = -state.wheelSpin[i];
      steering.quaternion.copy(q.setFromAxisAngle(steerAxis, -steer * STEERING_RATIO));

      // lights
      brake = state.brake;
      reverse = state.gear === -1;
      if (damage > 0.5) {
        flickerT -= dt;
        if (flickerT <= 0) {
          flickerOn = !flickerOn;
          flickerT = flickerOn ? 0.05 + Math.random() * 0.6 : 0.03 + Math.random() * 0.08;
        }
      } else flickerOn = true;
      applyLights();
    },

    setLights(o): void {
      if (o.headlights !== undefined) headlightsOn = o.headlights;
      if (o.brake !== undefined) brake = o.brake;
      if (o.reverse !== undefined) reverse = o.reverse;
      applyLights();
    },

    setEnvMap(tex: Texture | null, intensity: number): void {
      envTex = tex;
      envIntensity = intensity;
      for (const m of reflective) {
        m.envMap = envTex;
        m.needsUpdate = true;
      }
      applyEnv();
    },

    setDamage(d: number): void {
      damage = Math.min(1, Math.max(0, d));
      applyPaint();
      applyDamageParts();
      applyLights();
    },

    setVisible(v: boolean): void {
      root.visible = v;
    },

    setWetness(w: number): void {
      wetness = Math.min(1, Math.max(0, w));
      applyPaint();
    },

    setPaint(name: PaintName): void {
      if (!PAINTS[name]) return;
      paintName = name;
      applyPaint();
    },
  };

  applyPaint();
  applyLights();
  // keep single-sided where the source was single-sided (FrontSide default) — explicit for clarity
  for (const m of allMats) if (m.side !== DoubleSide) m.side = FrontSide;
  return visual;
}
